from math import ceil, sqrt

def z_of(a):
    return 1.96 if abs(a - 0.05) < 1e-9 else 2.58  # 仅支持 0.05/0.01

def sample_size(p1, mde, alpha=0.05, power=0.8):
    p2 = p1 + mde
    pbar = (p1 + p2) / 2
    return ceil(2 * pbar * (1 - pbar) * (z_of(alpha) + 0.84) ** 2 / mde ** 2)

def power_of(n, p1, p2, alpha=0.05):
    se0 = sqrt(2 * ((p1 + p2) / 2) * (1 - (p1 + p2) / 2) / n)
    se1 = sqrt((p1 * (1 - p1) + p2 * (1 - p2)) / n)
    return 0.5 * (1 + erf((abs(p2 - p1) - z_of(alpha) * se0) / se1))

